a<-commandArgs(TRUE);if(length(a)<4)stop("Usage: explain_score.R <model.rds> <background.csv> <out> <type> [nsim]");if(!requireNamespace("fastshap",quietly=TRUE)||!requireNamespace("shapviz",quietly=TRUE)||!requireNamespace("ggplot2",quietly=TRUE))stop("Install fastshap, shapviz, ggplot2");payload<-readRDS(a[1]);d<-read.csv(a[2],check.names=FALSE);out<-a[3];type<-tolower(a[4]);nsim<-if(length(a)>=5)as.integer(a[5])else 100L;dir.create(out,recursive=TRUE,showWarnings=FALSE);x<-d[,setdiff(names(d),c("ID","Time","Event")),drop=FALSE];fit<-if(is.list(payload)&&!is.null(payload$model))payload$model else payload
pf<-switch(type,rsf=function(o,n)as.numeric(predict(o,newdata=n)$predicted),gbm=function(o,n)as.numeric(predict(o,n,n.trees=payload$best_trees,type="link")),coxph=function(o,n)as.numeric(predict(o,n,type="lp")),lasso_cox=function(o,n)as.numeric(predict(o,newx=model.matrix(payload$matrix_terms,n)[,-1,drop=FALSE],s="lambda.min",type="link")),coxboost=function(o,n)as.numeric(predict(o,newdata=as.matrix(n),newtime=rep(1,nrow(n)),newstatus=rep(1,nrow(n)),type="lp")),survivalsvm=function(o,n)as.numeric(predict(o,n)$predicted),xgboost=function(o,n)as.numeric(predict(o,as.matrix(n))),plsrcox=function(o,n)as.numeric(predict(o,newdata=as.matrix(n),type="risk")),stop("Unsupported type; use native shapviz for xgboost or a custom wrapper for superpc"))
set.seed(123);sv<-fastshap::explain(fit,X=x,pred_wrapper=pf,nsim=nsim);viz<-shapviz::shapviz(sv,X=x);ggplot2::ggsave(file.path(out,paste0(type,"_shap_beeswarm.pdf")),shapviz::sv_importance(viz,kind="beeswarm"),width=7,height=5);ggplot2::ggsave(file.path(out,paste0(type,"_shap_bar.pdf")),shapviz::sv_importance(viz,kind="bar"),width=7,height=5);ggplot2::ggsave(file.path(out,paste0(type,"_shap_waterfall_row1.pdf")),shapviz::sv_waterfall(viz,row_id=1),width=6,height=5);saveRDS(list(shap=sv,shapviz=viz,target="model risk score",nsim=nsim),file.path(out,paste0(type,"_shap.rds")))
